function makeAsciiPineTree() {
  //     *
  //    ***
  //   *****
  //  *******
  // *********

  var treeHeight = 10;
  var starsCount, output, spaceCount;
  for (var i = 0; i < treeHeight; i++) {
    starsCount = i * 2 + 1;
    spaceCount = treeHeight - i;
    output = '';
    for (var k = 0; k < spaceCount; k++) {
      output += ' ';
    }
    for (var j = 0; j < starsCount; j++) {
      output += '*';
    }
    console.log(output);
  }
}
